import{z as n,x as l,o as e,c as B,q as t,j as A,D as a,d as i,s as r,S as s}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"激活重计算","description":"","frontmatter":{"title":"激活重计算","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dist-activation-recompute.md","filePath":"llm/dist-activation-recompute.md","lastUpdated":1791063341000}'),p={name:"llm/dist-activation-recompute.md"};function d(m,E,D,F,h,C){const o=l("Mermaid");return e(),B("div",null,[E[2]||(E[2]=t('<h1 id="激活重计算" tabindex="-1">激活重计算 <a class="header-anchor" href="#激活重计算" aria-label="Permalink to &quot;激活重计算&quot;">​</a></h1><div class="epigraph"><p>重计算是用算力买显存的汇率；汇率取决于重放的那个内核是算力受限还是带宽受限，不看名义 FLOPs。</p><footer>—— 据 Chen 等 2016 与 Korthikanti 等 2022 整理</footer></div><p><a href="/llm/dist-zero-stages">上一课</a>把参数侧的持久状态切成档，序列一长，显存墙就移到激活侧。主干课的<a href="/llm/activation-checkpointing">激活重计算</a>给了分段检查点的思想与「满层重计算约增三成 FLOPs」的口径；本课深钻工程里的三个问题：保存什么、重放什么、以及重计算在时间线上与通信重叠的冲突。不重讲分段原理。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「开重计算」不是一个布尔。满层重计算、只存大 GEMM 输入的选择性重计算、以及细到算子的粒度，FLOPs 增量能差出数倍；而墙上时间的增量还要再乘一个系数：重放路径上的内核若是带宽受限，它重放所花的时间占比远高于它的 FLOPs 占比。第二类缺口是正确性：重放必须复现同一个前向，随机状态、MoE 路由结果、 dropout 掩码没进检查点，反向拿到的就是另一个函数的梯度。第三类是冲突：反向被拉长后，原计划排在反向里的梯度通信窗口跟着变，重叠计划的粒度不改就会露底。</p><p>重叠计划的粒度不改就会露底。</p><p><span class="marginnote">「检查点」用游戏存档理解：前向跑到关键位置时，把当时的输入存档（而不是把所有中间画面都录下来）；反向需要某段画面时，从最近的存档重新打一遍那段。存档越多，重打越少、显存越省但存档本身占显存；存档越少则相反——「开重计算」就是在调这个存档密度。</span></p>',7)),(e(),A(s,null,{default:a(()=>[r(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q2%7B%22%E9%87%8D%E6%94%BE%E7%9A%84%E5%86%85%E6%A0%B8%E6%98%AF%E5%93%AA%E4%B8%80%E7%B1%BB%EF%BC%9F%22%7D%0A%20%20Q2%20--%3E%7C%22%E7%AE%97%E5%8A%9B%E5%8F%97%E9%99%90%EF%BC%9A%E5%A4%A7%20GEMM%22%7C%20FAST%5B%22%E9%87%8D%E6%94%BE%E6%97%B6%E9%97%B4%20%E2%89%88%20FLOPs%20%E5%8D%A0%E6%AF%94%EF%BC%8C%E5%8A%A0%E6%97%B6%E5%8F%AF%E6%8E%A7%22%5D%0A%20%20Q2%20--%3E%7C%22%E5%B8%A6%E5%AE%BD%E5%8F%97%E9%99%90%EF%BC%9A%E9%80%90%E5%85%83%E7%B4%A0%E5%B0%8F%E7%AE%97%E5%AD%90%22%7C%20SLOW%5B%22%E6%97%B6%E9%97%B4%E5%8D%A0%E6%AF%94%E8%BF%9C%E9%AB%98%E4%BA%8E%20FLOPs%20%E5%8D%A0%E6%AF%94%22%5D%0A%20%20SLOW%20--%3E%20FIX%5B%22%E9%80%89%E6%8B%A9%E6%80%A7%E9%87%8D%E8%AE%A1%E7%AE%97%EF%BC%9A%E6%8A%8A%E5%AE%83%E4%BB%AC%E6%8C%A1%E5%9C%A8%E9%87%8D%E6%94%BE%E8%B7%AF%E5%BE%84%E5%A4%96%22%5D%0A%20%20FAST%20--%3E%20BAL%5B%22%E6%B1%87%E7%8E%87%E5%8F%AF%E6%8E%A5%E5%8F%97%EF%BC%9A%E7%AE%97%E5%8A%9B%E6%8D%A2%E6%98%BE%E5%AD%98%22%5D%0A%20%20FIX%20--%3E%20BAL%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[i(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t('<h3 id="保存什么、重放什么" tabindex="-1">保存什么、重放什么 <a class="header-anchor" href="#保存什么、重放什么" aria-label="Permalink to &quot;保存什么、重放什么&quot;">​</a></h3><p>按「重放成本除以保存成本」给算子排序。保存便宜的存输入：LayerNorm、注意力的 qkv 投影这类小张量输入直接留；重放便宜的直接丢：逐元素的激活函数、bias 加法，反向从检查点两三步就能算回。结构性的是中间那档：注意力内部的大矩阵不再保存——FlashAttention 的在线 softmax 本来就不落整块矩阵，反向沿分块重算，这一段的重放由内核自身承担，不再算进框架的重计算预算。选择性口径由此而来：框架只负责存每层两三个 GEMM 输入，其余交给内核与分段。</p><p><span class="marginnote">满层重计算的名义增量约 +33%（每层多做一次前向，前向约占整步的三分之一）；选择性口径在长序列下常把这个数字压到一成多，差距全在「哪些张量没进检查点」。报重计算开销时只给一个百分比、不写粒度，别人无法复现你的 step time。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>落地按三步。第一步定粒度：按 Transformer 块设检查点，块内存 qkv 与 MLP 上投影的输入，这是默认档。第二步对长序列加序列并行：TP 组内把 Norm 与 Dropout 的激活沿序列维切开，这部分激活被分散而不被重算——省显存与省重计算是同一刀的两面。第三步校验数值路径：重放时 RNG 状态要回卷到与前向一致，MoE 的路由决定要缓存而不能重抽样，FP8 的 amax 统计与缩放缓存按同一前向口径读。三步做完，重放才是同一个函数的反向。</p><p><span class="marginnote">代个数字看序列并行省多少：TP 组为 8 卡时，Norm 与 Dropout 的激活沿序列维切成 8 份，这部分显存直接变为原来的八分之一，而且完全不用重算。对照满层重计算「省显存但全层多算一遍前向」，这一刀是纯赚——前提是这些算子本来就支持按序列切分。</span></p><p><span class="marginnote">为什么 MoE 路由不能重抽样：前向时路由器为每个 token 挑了专家，若重放时重新抽样，可能挑出另一批专家——反向算的就是另一个函数的梯度。所以路由决定必须当作检查点的一部分缓存下来，同理还有 dropout 掩码与 FP8 的 amax 统计。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么墙上时间增量可能偏离名义比例：算力受限的 GEMM 重放接近线性加时；带宽受限的逐元素算子 FLOPs 占比极低、时间占比却不低，满层重计算把大量这类小内核塞回时间线。所以选择性的收益不只是少算 GEMM，更是把小内核挡在重放路径外。与重叠的冲突是时间线问题：反向拉长后，梯度桶的就绪节奏变了，按旧节奏排的通信要么提前空等、要么挤到步末；重计算粒度每改一次，重叠计划要跟着对一遍，这对账归下一课。</p>',9)),(e(),A(s,null,{default:a(()=>[r(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACT%5B%22%E5%B1%82%E5%86%85%E6%BF%80%E6%B4%BB%E5%BC%A0%E9%87%8F%22%5D%20--%3E%20SORT%7B%22%E9%87%8D%E6%94%BE%E6%88%90%E6%9C%AC%20%2F%20%E4%BF%9D%E5%AD%98%E6%88%90%E6%9C%AC%22%7D%0A%20%20SORT%20--%3E%7C%E4%BF%9D%E5%AD%98%E4%BE%BF%E5%AE%9C%7C%20KEEP%5B%22%E7%95%99%E8%BE%93%E5%85%A5%3A%20LN%2C%20qkv%2C%20MLP%20%E6%8A%95%E5%BD%B1%22%5D%0A%20%20SORT%20--%3E%7C%E9%87%8D%E6%94%BE%E4%BE%BF%E5%AE%9C%7C%20DROP%5B%22%E7%9B%B4%E6%8E%A5%E4%B8%A2%3A%20%E9%80%90%E5%85%83%E7%B4%A0%E7%AE%97%E5%AD%90%22%5D%0A%20%20SORT%20--%3E%7C%E5%86%85%E6%A0%B8%E8%87%AA%E7%90%86%7C%20INNER%5B%22%E4%B8%8D%E8%90%BD%E7%9B%98%3A%20FlashAttention%20%E5%88%86%E5%9D%97%E9%87%8D%E7%AE%97%22%5D%0A%20%20KEEP%20--%3E%20RNG%5B%22%E6%A3%80%E6%9F%A5%E7%82%B9%E9%99%84%20RNG%20%E4%B8%8E%E8%B7%AF%E7%94%B1%E7%8A%B6%E6%80%81%22%5D%0A%20%20RNG%20--%3E%20CORRECT%5B%22%E9%87%8D%E6%94%BE%20%3D%20%E5%90%8C%E4%B8%80%E4%B8%AA%E5%89%8D%E5%90%91%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[i(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不重讲 \\(O(\\sqrt{n})\\) 的分段检查点与随机种子机制（Chen 2016 的原始口径，主干课已引）。重计算不省通信也不省优化器状态；瓶颈在参数侧时去加深重计算是花算力买不需要的东西。重放路径上不得引入新的数值分支：检查点前后的内核版本、精度策略必须钉死，否则「重放即漂移」，这类漂移在多卡上表现为难以归因的 loss 毛刺。</p><p><span class="marginnote">「重放即漂移」为什么难查：前向存档时用的是内核 A 的数值，重放时库升级悄悄换成了内核 B，两者差在小数点后第 7 位——单看哪一步都没错，但几百万步累积后 loss 曲线上出现毫无规律的毛刺，且只在部分卡上出现。钉死内核版本与精度策略，就是把这条隐患从源头焊死。</span>反向被拉长之后通信怎么排，是下一课的入口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>重计算粒度是连续谱：满层、选择性、内核自理，FLOPs 增量差数倍，报口径必须带粒度。</li><li>汇率由内核类型决定：带宽受限算子的重放时间占比远高于 FLOPs 占比。</li><li>重放必须复现同一前向：RNG 回卷、路由缓存、amax 口径一起进检查点。</li><li>序列并行与重计算是同一刀的两面：激活先分散、剩下才谈重算。</li><li>出处：Chen 等，Training Deep Nets with Sublinear Memory Cost，2016；Korthikanti 等，Reducing Activation Recomputation in Large Transformer Models，2022。</li></ul>',5))])}const u=n(p,[["render",d]]);export{_ as __pageData,u as default};
